import{z as o,x as s,o as A,c as T,q as l,j as r,D as a,d as e,s as n,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"量化感知训练","description":"","frontmatter":{"title":"量化感知训练","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/num-qat.md","filePath":"llm/num-qat.md","lastUpdated":1791063341000}'),d={name:"llm/num-qat.md"};function D(p,E,m,C,F,Q){const t=s("Mermaid");return A(),T("div",null,[E[2]||(E[2]=l('<h1 id="量化感知训练" tabindex="-1">量化感知训练 <a class="header-anchor" href="#量化感知训练" aria-label="Permalink to &quot;量化感知训练&quot;">​</a></h1><div class="epigraph"><p>与其部署时被量化噪声吓一跳，不如训练时就让它进场；难在反向穿过取整的那一步，只能靠估计。</p><footer>—— 据 Jacob et al., Quantization and Training of Neural Networks for Efficient Integer-Arithmetic-Only Inference, CVPR 2018 整理</footer></div><p><a href="/llm/num-stochastic-rounding">上一课</a>处理的是「真值怎么写回存储」，本课把低精度再往前推一步：前向就按低精度算。量化感知训练（QAT）把量化噪声从部署时刻搬进训练环。假量化图的完整机制——前向取整、STE 回传、整数-only 的边界——在 <a href="/llm/qat">QAT</a> 已写，本课不重复推导，只从这门课的主线补三件事：量化噪声与优化器的耦合、尺度该学还是该冻、以及 QAT 在什么意义上让「训练到部署」这段路更稳。格式课的三份账（宽度、尺子、舍入）在这里收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PTQ 把量化当部署后处理：权重停在格子之间，一步量化等于给每层加一份从未见过的噪声，部署敏感的模型直接掉点。QAT 的答案是让梯度把参数推到「量化后仍然好」的区域。但从训练稳定的视角看，这是把一个受控系统改成了带执行器噪声的系统：前向每层多一段台阶函数，反向的梯度是有偏估计（STE），损失的随机性变强、梯度信噪比变低。QAT 不是「更稳的训练」，是「为部署 stability 付出训练期 variance」的交易——这笔账要用这门课前四课的语言记账。</p><p><span class="marginnote">术语翻译：「假量化」就是训练时先照常算浮点，再手动把数值按到最近的格点上继续前向——存的仍是浮点数，但值已带着取整。「STE」（直通估计器）是反向的补救：取整这一步没有正常导数，就假装它不存在，让梯度原样穿过去——方向有系统偏差，但比完全断掉强。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>稳定性视角的配方，逐条对应一种噪声来源。主权重保持浮点：假量化只出现在前向仿真里，导出整数是训练结束的一次冻结——写回偏置由浮点主权重吸收（第一课的规则）。假量化只套线性层的权重与输入，softmax、归一化、损失留宽（第一课规则二的同一张清单）。尺度先按校准统计初始化，训练中慢更新或干脆冻结：尺度乱跳等于每步换一套格子，把 STE 的噪声按格宽放大（第二课的尺子合同在训练态的版本）。学习率低于原训练：STE 的偏置在细步长下漂移慢。</p><p><span class="marginnote">数字实例：尺度为什么要冻。设某层格宽 0.1，取整噪声至多 0.05，是固定地板；若尺度每步都在变，同一个权重这一步被取整到 0.3、下一步格子换了又取整到 0.6——「噪声至多半个格宽」的前提没了，STE 的偏差被逐格放大，梯度信噪比随尺度抖动一起崩。</span></p>',9)),(A(),r(i,null,{default:a(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%B5%AE%E7%82%B9%E4%B8%BB%E6%9D%83%E9%87%8D%22%5D%20--%3E%20FQ%5B%22%E5%89%8D%E5%90%91%E6%8F%92%E5%81%87%E9%87%8F%E5%8C%96%EF%BC%88%E5%B0%BA%E5%BA%A6%E5%86%BB%E7%BB%93%E6%88%96%E6%85%A2%E6%9B%B4%E6%96%B0%EF%BC%89%22%5D%0A%20%20FQ%20--%3E%20GEMM%5B%22%E4%BB%BF%E7%9C%9F%E4%BD%8E%E7%B2%BE%E5%BA%A6%20GEMM%22%5D%0A%20%20GEMM%20--%3E%20L%5B%22%E4%BB%BB%E5%8A%A1%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20L%20--%3E%20STE%5B%22STE%20%E5%9B%9E%E4%BC%A0%EF%BC%88%E6%9C%89%E5%81%8F%E4%BC%B0%E8%AE%A1%EF%BC%89%22%5D%0A%20%20STE%20--%3E%20OPT%5B%22%E5%AE%BD%E6%A0%BC%E5%BC%8F%E4%BC%98%E5%8C%96%E5%99%A8%E6%9B%B4%E6%96%B0%E4%B8%BB%E6%9D%83%E9%87%8D%22%5D%0A%20%20OPT%20--%3E%20W%0A%20%20FQ%20--%3E%20MON%5B%22%E7%9B%91%E6%8E%A7%EF%BC%9A%E9%87%8F%E5%8C%96%E5%99%AA%E5%A3%B0%E6%AF%94%E3%80%81%E5%B0%BA%E5%BA%A6%E5%BA%8F%E5%88%97%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("p",null,"监控面比普通微调多两项：量化噪声比（前向仿真与宽格式前向的输出差）与尺度序列的抖动幅度，这两条曲线是第四课仪表盘的 QAT 特供。",-1)),E[4]||(E[4]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=B("p",null,"QAT 的「稳」有两层，不能混说。第一层是部署稳：训练足够久时，权重大质量迁到台阶中心，推理取整不再跨边界——部署时刻不再有分布迁移，这是 PTQ 给不了的。第二层常被误读成「训练稳」：STE 是有偏梯度，与上一课 SR 的无偏噪声不同类，Adam 的二阶矩会把低信噪比方向的步长归一化放大，偏置不会像方差那样被 batch 平均掉。所以 QAT 训练更像在噪声地板上走路：能走，但每一步的方向都有系统误差，靠训练时长与数据量把偏置的积分效应压小。",-1)),(A(),r(i,null,{default:a(()=>[n(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20PTQ%5B%22PTQ%EF%BC%9A%E9%83%A8%E7%BD%B2%E6%97%B6%E6%89%8D%E9%87%8F%E5%8C%96%22%5D%0A%20%20%20%20W1%5B%22%E8%AE%AD%E7%BB%83%E5%AE%8C%E6%88%90%EF%BC%9A%E6%B5%AE%E7%82%B9%E6%9D%83%E9%87%8D%22%5D%20--%3E%20Q1%5B%22%E4%B8%80%E6%AD%A5%E9%87%8F%E5%8C%96%EF%BC%9A%E5%B0%B1%E8%BF%91%E5%8F%96%E6%95%B4%22%5D%0A%20%20%20%20Q1%20--%3E%20C1%5B%22%E9%83%A8%E5%88%86%E6%9D%83%E9%87%8D%E8%90%BD%E5%9C%A8%E5%8F%B0%E9%98%B6%E8%BE%B9%E7%BC%98%22%5D%0A%20%20%20%20C1%20--%3E%20D1%5B%22%E6%8E%A8%E7%90%86%E8%B7%A8%E8%BE%B9%E7%95%8C%EF%BC%9A%E5%88%86%E5%B8%83%E8%BF%81%E7%A7%BB%EF%BC%8C%E6%8E%89%E7%82%B9%22%5D%0A%20%20end%0A%20%20subgraph%20QATP%5B%22QAT%EF%BC%9A%E8%AE%AD%E7%BB%83%E6%97%B6%E5%B0%B1%E9%87%8F%E5%8C%96%22%5D%0A%20%20%20%20W2%5B%22%E8%AE%AD%E7%BB%83%E5%90%AB%E5%81%87%E9%87%8F%E5%8C%96%22%5D%20--%3E%20Q2%5B%22%E6%A2%AF%E5%BA%A6%E6%8A%8A%E6%9D%83%E9%87%8D%E6%8E%A8%E5%90%91%E5%8F%B0%E9%98%B6%E4%B8%AD%E5%BF%83%22%5D%0A%20%20%20%20Q2%20--%3E%20C2%5B%22%E6%9D%83%E9%87%8D%E7%A8%B3%E5%AE%9A%E5%9C%A8%E6%A0%BC%E5%BF%83%E9%99%84%E8%BF%91%22%5D%0A%20%20%20%20C2%20--%3E%20D2%5B%22%E9%83%A8%E7%BD%B2%E5%8F%96%E6%95%B4%E4%B8%8D%E5%86%8D%E8%B7%A8%E8%BE%B9%E7%95%8C%EF%BC%9A%E4%B8%8D%E6%8E%89%E7%82%B9%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">直觉类比：量化像把连续斜坡改成一级级台阶。PTQ 是球先在斜坡上放稳，部署时突然抽走斜坡换成台阶，球滚到哪全看运气；QAT 是训练时就在台阶上滚球，久而久之球都停在每级台阶的正中，之后抽换斜坡也无所谓。</span></p><p>与训练侧低精度的关系是共用预算而非叠加：若训练本来就在 FP8 GEMM 上跑（第二课），QAT 的假量化目标格式应与实际核一致，否则是给同一批权重叠两套不同的量化噪声——预算翻倍而收益不叠。</p><p><span class="marginnote">从浮点全参做 QAT，与从量化检查点「再训练」不是同一实验：后者若不允许 STE 穿过整数，只是在离散点上跳，通常训不动。主权重必须浮点，直到导出那一刻。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>成本线先画清楚：70B 级全网 QAT 接近再训一遍，理性顺序仍是 PTQ 不够再对敏感层 QAT。4-bit 激活的台阶太宽，STE 的「可以滑过去」幻觉更强，常不如把激活留在宽格式只量化权重。QAT 会拟合训练分布：用通用语料做 QAT 等于重开一次对齐，安全与拒答行为都可能漂，应在下游 SFT 数据上短微调并当另一次对齐验收。最后与 <a href="/llm/qlora">QLoRA</a> 分家：4-bit 冻结基座加浮点适配器不是 QAT，别叠成一句「都是 4-bit 训练」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>QAT 把量化噪声搬进训练环：部署稳的收益，用训练期方差与有偏梯度换。</li><li>配方逐条对应噪声源：浮点主权重、线性层假量化、尺度冻结或慢更新、低学习率。</li><li>STE 的偏置与 SR 的方差不同类，不会随 batch 平均；靠时长与数据量压积分效应。</li><li>QAT 的目标格式应与实际低精度核一致，两套噪声不叠加记账。</li><li>成本接近再训练，默认先 PTQ；数据域错位会破坏对齐。</li><li>出处：Jacob et al., CVPR 2018；本课程格式与缩放各课的记账口径。</li></ul>',7))])}const f=o(d,[["render",D]]);export{u as __pageData,f as default};
